-- Versioned P04 receipt: seed only, never replays over deliberate edits/revocations.
SELECT g.workspace_id,g.user_id,g.company_id,'service.work_order.read',g.scope_type,g.scope_id,g.site_id,g.valid_from,g.valid_to
FROM ppo.permission_grants g WHERE g.capability='service.ticket.read' AND g.valid_from<=clock_timestamp() AND (g.valid_to IS NULL OR g.valid_to>clock_timestamp()) ON CONFLICT DO NOTHING;
SELECT g.workspace_id,g.user_id,g.company_id,cap,g.scope_type,g.scope_id,g.site_id,g.valid_from,g.valid_to
FROM ppo.permission_grants g CROSS JOIN (VALUES('service.work_order.edit'),('service.scope.authorise'),('service.readiness.assess')) AS capabilities(cap)
WHERE g.capability='service.ticket.edit' AND g.valid_from<=clock_timestamp() AND (g.valid_to IS NULL OR g.valid_to>clock_timestamp()) ON CONFLICT DO NOTHING;

UPDATE ppo.work_orders SET scope_revision_id='91000000-0000-4000-8000-000000000001' WHERE id='90000000-0000-4000-8000-000000000001';
UPDATE ppo.work_orders SET scope_revision_id='91000000-0000-4000-8000-000000000002' WHERE id='90000000-0000-4000-8000-000000000002';
WITH snapshot AS (SELECT jsonb_build_object('schema_version',1,'synthetic',true,'source','P04 SQL fixture','tickets',(SELECT jsonb_agg(jsonb_build_object('id',t.id,'display_number',t.display_number,'version',t.version,'status',t.status,'issue_disposition',l.issue_disposition) ORDER BY t.id) FROM ppo.work_order_tickets l JOIN ppo.tickets t ON (t.workspace_id,t.id)=(l.workspace_id,l.ticket_id) WHERE l.work_order_id=r.work_order_id),'scope',to_jsonb(r),'coverage',to_jsonb(c),'authority',to_jsonb(d),'items',(SELECT jsonb_agg(to_jsonb(i)||jsonb_build_object('assets',(SELECT jsonb_agg(jsonb_build_object('asset_id',a.id,'display_number',a.display_number,'description',a.description,'identity_status',a.identity_status,'asset_version',a.version,'serial',a.serial,'model',a.model,'configuration_id',sa.configuration_id)) FROM ppo.scope_assets sa JOIN ppo.assets a ON a.id=sa.asset_id WHERE sa.scope_item_id=i.id))) FROM ppo.scope_items i WHERE i.scope_revision_id=r.id),'assets',(SELECT jsonb_agg(to_jsonb(a)) FROM ppo.scope_assets a WHERE a.scope_revision_id=r.id),'readiness',(SELECT jsonb_agg(to_jsonb(a)) FROM ppo.readiness_assessments a WHERE a.scope_revision_id=r.id),'financial_disposition','PendingFinanceReview') AS body FROM ppo.scope_revisions r JOIN ppo.coverage_assessments c ON c.id=r.coverage_assessment_id JOIN ppo.document_references d ON d.id=r.authority_evidence_ref WHERE r.id='91000000-0000-4000-8000-000000000002')
UPDATE ppo.scope_revisions SET approved_by='30000000-0000-4000-8000-000000000001',approved_at=clock_timestamp(),approved_snapshot=snapshot.body,content_hash=encode(sha256(convert_to(snapshot.body::text,'UTF8')),'hex') FROM snapshot WHERE id='91000000-0000-4000-8000-000000000002';
